# Let's attempt to implement a simple hck in Python and test against original for many random cases, to see how often our simple logic matches original for pure cases.

import subprocess, random, string, os, re, sys, tempfile, gzip

BIN="./executable"

def run_original(inp, args):
    proc = subprocess.run([BIN]+args, input=inp.encode(), stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    return proc.stdout.decode(), proc.stderr.decode(), proc.returncode

def parse_fields_spec(spec):
    # returns list of (low, high) where high None means inf, low None means 1? Actually "-5" => low=1 high=5, "5-" => low=5 high=inf, "-" should error
    # Also single number
    # Returns list of ranges in order, or error string
    parts = spec.split(',')
    ranges = []
    for part in parts:
        if part == "":
            return None, f"Failed to parse field: "
        # check for multiple dashes: count '-' but need to handle leading '-'
        # For simplicity, use logic:
        # If part starts with '-' and contains only one '-' at start: "-M"
        # If part ends with '-' and contains only one '-' at end: "N-"
        # If part == "-": error
        # Else if '-' in part: split by '-', should be exactly 2 parts non-empty? But need to handle negative? No negative allowed.
        # Use regex: ^(\d*)-(\d*)$ with at least one digit on at least one side, and not both empty
        if part == "-":
            return None, f"Failed to parse field: "
        if part.count('-') > 1:
            # could be like "1-2-3"
            return None, f"Failed to parse field: {part}"
        if '-' in part:
            left, right = part.split('-', 1)
            if left == "" and right == "":
                return None, f"Failed to parse field: "
            if left == "":
                # -M
                try:
                    high = int(right)
                except:
                    return None, f"Failed to parse field: {part}"
                if high == 0:
                    return None, f"Fields and positions are numbered from 1: 0"
                low = 1
            elif right == "":
                # N-
                try:
                    low = int(left)
                except:
                    return None, f"Failed to parse field: {part}"
                if low == 0:
                    return None, f"Fields and positions are numbered from 1: 0"
                high = None # inf
            else:
                try:
                    low = int(left)
                    high = int(right)
                except:
                    return None, f"Failed to parse field: {part}"
                if low == 0 or high == 0:
                    return None, f"Fields and positions are numbered from 1: 0"
                if low > high:
                    return None, f"High end of range less than low end of range: {part}"
            ranges.append((low, high))
        else:
            # single number
            try:
                n = int(part)
            except:
                return None, f"Failed to parse field: {part}"
            if n == 0:
                return None, f"Fields and positions are numbered from 1: 0"
            ranges.append((n, n))
    return ranges, None

def expand_ranges(ranges, max_fields):
    # ranges is list of (low, high) where high None = inf
    seen = set()
    result = []
    for low, high in ranges:
        if high is None:
            high = max_fields
        else:
            high = min(high, max_fields)
        for i in range(low, high+1):
            if i not in seen:
                seen.add(i)
                result.append(i)
    return result

def test_simple():
    # test field parsing vs original
    for spec in ["1", "1,2", "1-3", "-3", "3-", "1-3,2", "4-,1,5-8", "2,1,4", "1,5,2"]:
        inp = "a b c d e f g h i j\n"
        args = ["-f"+spec, "-D,"]
        out_orig, err_orig, rc_orig = run_original(inp, args)
        # our parse
        ranges, err = parse_fields_spec(spec)
        if err:
            print(f"spec {spec} we error {err} but orig rc {rc_orig} err {err_orig!r}")
            continue
        expanded = expand_ranges(ranges, 10)
        # build output
        fields = inp.strip().split()
        selected = []
        seen=set()
        for low,high in ranges:
            h = high if high is not None else 10
            for i in range(low, min(h,10)+1):
                if i not in seen:
                    seen.add(i)
                    selected.append(fields[i-1])
        out = ",".join(selected)+"\n"
        if out != out_orig:
            print(f"MISMATCH spec {spec}: ours {out!r} orig {out_orig!r}")
        else:
            print(f"OK spec {spec} => {out.strip()}")

test_simple()
