        Err(e) => {
            // clap errors should be printed as original does
            // Original prints error like "error: invalid value 'bad' for '--compression-threads <COMPRESSION_THREADS>': ..."
            e.exit();
        }
    };

    // Handle help and version - clap does automatically, but we need to ensure custom.

    // Get args
    let input_files: Vec<String> = matches.get_many::<String>("input").map(|v| v.map(|s| s.to_string()).collect()).unwrap_or_default();
    let output_file = matches.get_one::<String>("output").map(|s| s.to_string());
    let delimiter_str = matches.get_one::<String>("delimiter").unwrap().to_string();
    let delim_is_literal = matches.get_flag("delim_is_literal");
    let use_input_delim = matches.get_flag("use_input_delim");
    let mut output_delimiter_arg = matches.get_one::<String>("output_delimiter").map(|s| s.to_string());
    let output_delimiter_default = output_delimiter_arg.is_none() || matches.value_source("output_delimiter").unwrap() == clap::parser::ValueSource::DefaultValue;
    // Actually we need to know if user explicitly set -D
    let output_delim_explicit = matches.contains_id("output_delimiter") && matches.value_source("output_delimiter").unwrap() != clap::parser::ValueSource::DefaultValue;
    // Simpler: check if -D provided by checking if arg present? We'll use contains_id and not default
    // For now, we treat output_delimiter_arg as always Some, but we need to know if explicit.
    // Let's get raw presence: if user passed -D, then value_source is CommandLine.
    let output_delim_is_default = if let Some(source) = matches.value_source("output_delimiter") {
        source == clap::parser::ValueSource::DefaultValue
    } else {
        true
    };

    let fields_opt = matches.get_one::<String>("fields").map(|s| s.to_string());
    let exclude_opt = matches.get_one::<String>("exclude").map(|s| s.to_string());
    let exclude_headers: Vec<String> = matches.get_many::<String>("exclude_header").map(|v| v.map(|s| s.to_string()).collect()).unwrap_or_default();
    let header_fields: Vec<String> = matches.get_many::<String>("header_field").map(|v| v.map(|s| s.to_string()).collect()).unwrap_or_default();
    let header_is_regex = matches.get_flag("header_is_regex");
    let try_decompress = matches.get_flag("try_decompress");
    let try_compress = matches.get_flag("try_compress");
    let compression_threads_str = matches.get_one::<String>("compression_threads").unwrap().to_string();
    let compression_level_str = matches.get_one::<String>("compression_level").unwrap().to_string();
    let no_mmap = matches.get_flag("no_mmap");
    let crlf = matches.get_flag("crlf");

    // Validate compression_threads and level - should be integers
    // Original error: "error: invalid value 'bad' for '--compression-threads <COMPRESSION_THREADS>': invalid digit found in string"
    // Clap does this automatically if we set value_parser to integer, but we set as string default, so we need to parse ourselves and produce same error.

    // Actually we used default_value as string, but we didn't set value_parser. So clap will accept any string. We need to set value_parser to clap::value_parser!(u32) to get same error? Let's check clap's error message for invalid digit - it would be similar.
    // To simplify, we will parse manually and if fails, print error and exit with code 2 as clap does.

    // Parse threads
    if let Err(_) = compression_threads_str.parse::<u32>() {
        eprintln!("error: invalid value '{}' for '--compression-threads <COMPRESSION_THREADS>': invalid digit found in string\n\nFor more information, try '--help'.", compression_threads_str);
        process::exit(2);
    }
    if let Err(_) = compression_level_str.parse::<u32>() {
        eprintln!("error: invalid value '{}' for '--compression-level <COMPRESSION_LEVEL>': invalid digit found in string\n\nFor more information, try '--help'.", compression_level_str);
        process::exit(2);
    }

    // Parse fields
    let fields_ranges = if let Some(ref f) = fields_opt {
        match parse_field_spec(f) {
            Ok(r) => Some(r),
            Err(msg) => {
                // log error with timestamp like original
                let ts = chrono::Utc::now().format("%Y-%m-%dT%H:%M:%SZ");
                eprintln!("[{} ERROR hck] {}", ts, msg);
                process::exit(1);
            }
        }
    } else {
        None
    };

    let exclude_ranges = if let Some(ref e) = exclude_opt {
        match parse_field_spec(e) {
            Ok(r) => Some(r),
            Err(msg) => {
                let ts = chrono::Utc::now().format("%Y-%m-%dT%H:%M:%SZ");
                eprintln!("[{} ERROR hck] {}", ts, msg);
                process::exit(1);
            }
        }
    } else {
        None
    };

    // Determine input delimiter literal processed
    let input_delim_literal_string: Option<String> = if delim_is_literal {
        Some(unescape_literal(&delimiter_str))
    } else {
        None
    };

    // Determine output delimiter
    let output_delim_processed: String = if let Some(ref od) = output_delimiter_arg {
        // If user explicitly set -D, unescape it. If default, default is "\t" which is tab.
        if output_delim_is_default {
            "\t".to_string()
        } else {
            unescape_literal(od)
        }
    } else {
        "\t".to_string()
    };

    // If -I and input is literal and output delim is default (not explicit), use input delim as output delim
    let final_output_delim = if use_input_delim && delim_is_literal && output_delim_is_default {
        input_delim_literal_string.clone().unwrap_or(output_delim_processed)
    } else {
        output_delim_processed
    };

    // For regex delimiter, compile
    let regex_delim: Option<Regex> = if !delim_is_literal {
        if delimiter_str.is_empty() {
            None
        } else {
            match Regex::new(&delimiter_str) {
                Ok(r) => Some(r),
                Err(e) => {
                    // What does original do for invalid regex? Let's test: -d'[' should error?
                    // We haven't tested. For now, just treat as literal? Or error.
                    // Let's attempt to mimic: if regex invalid, maybe error.
                    let ts = chrono::Utc::now().format("%Y-%m-%dT%H:%M:%SZ");
                    eprintln!("[{} ERROR hck] Invalid regex: {}", ts, e);
                    process::exit(1);
                }
            }
        }
    } else {
        None
    };

    // For literal delimiter, we have string
    let literal_delim: Option<String> = if delim_is_literal {
        if delimiter_str.is_empty() {
            None
        } else {
            Some(unescape_literal(&delimiter_str))
        }
    } else {
        None
    };

    // Prepare output writer
    let output_writer: Box<dyn Write> = if let Some(out_path) = output_file {
        match File::create(&out_path) {
            Ok(f) => {
                if try_compress {
                    // gzip compress
                    let level = compression_level_str.parse::<u32>().unwrap_or(6);
                    // Use flate2
                    let encoder = flate2::write::GzEncoder::new(f, flate2::Compression::new(level));
                    Box::new(encoder)
                } else {
                    Box::new(f)
                }
            }
            Err(e) => {
                eprintln!("Error: Failed to open {} for writing.\n\nCaused by:\n    {}\n", out_path, e);
                process::exit(1);
            }
        }
    } else {
        if try_compress {
            let level = compression_level_str.parse::<u32>().unwrap_or(6);
            let stdout = io::stdout();
            let encoder = flate2::write::GzEncoder::new(stdout, flate2::Compression::new(level));
            Box::new(encoder)
        } else {
            Box::new(io::stdout())
        }
    };

    // Use BufWriter for efficiency
    let mut writer = std::io::BufWriter::new(output_writer);

    // Determine if header mode
    let header_mode = !header_fields.is_empty() || !exclude_headers.is_empty();

    // Prepare header field regexes if needed
    let header_field_regexes: Vec<Regex> = if header_is_regex {
        let mut vec = Vec::new();
        for pat in &header_fields {
            match Regex::new(pat) {
                Ok(r) => vec.push(r),
                Err(e) => {
                    // If header regex invalid, what does original do? Probably error No headers matched? Or regex error?
                    // For now, treat as never matching? But better to error?
                    // Let's test: -r -F '[' should?
                    // We haven't tested. We'll just treat invalid as never matching and log?
                    // For simplicity, if invalid, then it won't match, leading to No headers matched error.
                    // But we should try to compile with same regex engine as original (likely regex crate). So invalid regex would error at runtime? Let's check original behavior for invalid header regex.
                    // We haven't tested, but we can assume it would error? Might be treated as no match.
                    // We'll push a regex that never matches
                    // For now, create regex that never matches by using a regex that fails to compile, we skip.
                    // We'll log error? Let's just create empty vec and later handle.
                    // Actually, if regex invalid, original might error "No headers matched" or similar.
                    // We'll treat as regex that never matches.
                    vec.push(Regex::new("$^").unwrap()); // never matches
                }
            }
        }
        vec
    } else {
        Vec::new()
    };

    let exclude_header_regexes: Vec<Regex> = if header_is_regex {
        let mut vec = Vec::new();
        for pat in &exclude_headers {
            match Regex::new(pat) {
                Ok(r) => vec.push(r),
                Err(_) => {
                    vec.push(Regex::new("$^").unwrap());
                }
            }
        }
        vec
    } else {
        Vec::new()
    };

    // For each input file, process
    // If no input files, read from stdin
    if input_files.is_empty() {
        // stdin
        let stdin = io::stdin();
        let reader = BufReader::new(stdin);
        if let Err(e) = process_reader(reader, &mut writer, &literal_delim, &regex_delim, &fields_ranges, &exclude_ranges, &header_fields, &exclude_headers, &header_field_regexes, &exclude_header_regexes, header_is_regex, header_mode, &final_output_delim, crlf, try_compress) {
            // handle error?
            eprintln!("Error: {}", e);
            process::exit(1);
        }
    } else {
        for (file_idx, file_path) in input_files.iter().enumerate() {
            // Check if file is "-" meaning stdin
            if file_path == "-" {
                let stdin = io::stdin();
                let reader = BufReader::new(stdin);
                if let Err(e) = process_reader(reader, &mut writer, &literal_delim, &regex_delim, &fields_ranges, &exclude_ranges, &header_fields, &exclude_headers, &header_field_regexes, &exclude_header_regexes, header_is_regex, header_mode, &final_output_delim, crlf, try_compress) {
                    eprintln!("Error: {}", e);
                    process::exit(1);
                }
                continue;
            }

            // Check file existence
            // If try_decompress, check extension and attempt decompress
            let path = std::path::Path::new(file_path);
            if !path.exists() {
                let ts = chrono::Utc::now().format("%Y-%m-%dT%H:%M:%SZ");
                eprintln!("[{} ERROR hck] No such file or directory (os error 2)", ts);
                continue;
            }

            // If try_decompress, attempt to decompress based on extension
            let mut reader: Box<dyn BufRead> = if try_decompress {
                match try_decompress_file(file_path) {
                    Ok((r, _)) => r,
                    Err((msg, is_external)) => {
                        // msg is error message to print? For internal, msg is "invalid gzip header" etc.
                        // For external, msg is the full error with dashed lines? Actually we need to print as original does.
                        // The original for external prints:
                        // [timestamp ERROR hck] 
                        //     -------------------------------------------------------------------------------
                        //     <binary>: <file>: <error>
                        //     -------------------------------------------------------------------------------
                        // For internal, prints "[timestamp ERROR hck] <msg>"
                        // For our try_decompress_file, we return Err((msg, is_external)) where msg is the inner error without timestamp? Let's handle.
                        if is_external {
                            let ts = chrono::Utc::now().format("%Y-%m-%dT%H:%M:%SZ");
                            eprintln!("[{} ERROR hck] \n    -------------------------------------------------------------------------------\n    {}\n    -------------------------------------------------------------------------------", ts, msg);
                        } else {
                            let ts = chrono::Utc::now().format("%Y-%m-%dT%H:%M:%SZ");
                            eprintln!("[{} ERROR hck] {}", ts, msg);
                        }
                        continue;
                    }
                }
            } else {
                // No decompress, just open file
                match File::open(file_path) {
                    Ok(f) => Box::new(BufReader::new(f)),
                    Err(e) => {
                        let ts = chrono::Utc::now().format("%Y-%m-%dT%H:%M:%SZ");
                        eprintln!("[{} ERROR hck] {} (os error {})", ts, e, e.raw_os_error().unwrap_or(2));
                        continue;
                    }
                }
            };

            // Now process this reader
            // For header mode, each file's first line is header
            // So we need to process per file, not combine

            if let Err(e) = process_reader_file(reader, &mut writer, &literal_delim, &regex_delim, &fields_ranges, &exclude_ranges, &header_fields, &exclude_headers, &header_field_regexes, &exclude_header_regexes, header_is_regex, header_mode, &final_output_delim, crlf, file_idx == 0) {
                eprintln!("Error: {}", e);
                process::exit(1);
            }
        }
    }

    writer.flush().unwrap();
}

fn unescape_literal(s: &str) -> String {
    let mut result = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            if let Some(next) = chars.next() {
                match next {
                    't' => result.push('\t'),
                    'n' => result.push('\n'),
                    'r' => result.push('\r'),
                    '0' => result.push('\0'),
                    '\\' => result.push('\\'),
                    'x' => {
                        // Need 2 hex digits
                        let h1 = chars.next();
                        let h2 = chars.next();
                        if let (Some(c1), Some(c2)) = (h1, h2) {
                            if c1.is_ascii_hexdigit() && c2.is_ascii_hexdigit() {
                                let hex_str = format!("{}{}", c1, c2);
                                if let Ok(byte) = u8::from_str_radix(&hex_str, 16) {
                                    result.push(byte as char);
                                } else {
                                    // Invalid hex, keep literal \x + chars?
                                    result.push('\\');
                                    result.push('x');
                                    result.push(c1);
                                    result.push(c2);
                                }
                            } else {
                                // Not hex, keep literal \x + chars
                                result.push('\\');
                                result.push('x');
                                result.push(c1);
                                result.push(c2);
                            }
                        } else {
                            // Not enough chars for \x, keep literal
                            result.push('\\');
                            result.push('x');
                            if let Some(c1) = h1 {
                                result.push(c1);
                            }
                            if let Some(c2) = h2 {
                                result.push(c2);
                            }
                        }
                    }
                    _ => {
                        // For other escapes like \s, \d, keep as \ + char
                        result.push('\\');
                        result.push(next);
                    }
                }
            } else {
                result.push('\\');
            }
        } else {
            result.push(c);
        }
    }
    result
}

fn parse_field_spec(s: &str) -> Result<Vec<(usize, Option<usize>)>, String> {
    // Returns Vec of (low, high Option) where None means inf
    // Error string is like "Fields and positions are numbered from 1: 0" or "High end of range less than low end of range: 1-0" or "Failed to parse field: X"
    let mut ranges = Vec::new();
    for part in s.split(',') {
        if part.is_empty() {
            return Err(format!("Failed to parse field: "));
        }
        if part == "-" {
            return Err(format!("Failed to parse field: "));
        }
        // Check for multiple dashes: if more than one '-' and not leading/trailing case?
        // For simplicity, if count('-') >1, error
        if part.matches('-').count() > 1 {
            return Err(format!("Failed to parse field: {}", part));
        }
        if part.contains('-') {
            let mut split = part.splitn(2, '-');
            let left = split.next().unwrap();
            let right = split.next().unwrap();
            if left.is_empty() && right.is_empty() {
                return Err(format!("Failed to parse field: "));
            }
            if left.is_empty() {
                // -M
                match right.parse::<usize>() {
                    Ok(high) => {
                        if high == 0 {
                            return Err(format!("Fields and positions are numbered from 1: 0"));
                        }
                        ranges.push((1, Some(high)));
                    }
                    Err(_) => {
                        return Err(format!("Failed to parse field: {}", part));
                    }
                }
            } else if right.is_empty() {
                // N-
                match left.parse::<usize>() {
                    Ok(low) => {
                        if low == 0 {
                            return Err(format!("Fields and positions are numbered from 1: 0"));
                        }
                        ranges.push((low, None));
                    }
                    Err(_) => {
                        return Err(format!("Failed to parse field: {}", part));
                    }
                }
            } else {
                // N-M
                let low_res = left.parse::<usize>();
                let high_res = right.parse::<usize>();
                match (low_res, high_res) {
                    (Ok(low), Ok(high)) => {
                        if low == 0 || high == 0 {
                            return Err(format!("Fields and positions are numbered from 1: 0"));
                        }
                        if low > high {
                            return Err(format!("High end of range less than low end of range: {}", part));
                        }
                        ranges.push((low, Some(high)));
                    }
                    _ => {
                        return Err(format!("Failed to parse field: {}", part));
                    }
                }
            }
        } else {
            // single number
            match part.parse::<usize>() {
                Ok(n) => {
                    if n == 0 {
                        return Err(format!("Fields and positions are numbered from 1: 0"));
                    }
                    ranges.push((n, Some(n)));
                }
                Err(_) => {
                    return Err(format!("Failed to parse field: {}", part));
                }
            }
        }
    }
    Ok(ranges)
}

fn expand_ranges_for_line(ranges: &Vec<(usize, Option<usize>)>, max_fields: usize) -> Vec<usize> {
    let mut seen = HashSet::new();
    let mut result = Vec::new();
    for (low, high_opt) in ranges {
        let high = match high_opt {
            Some(h) => std::cmp::min(*h, max_fields),
            None => max_fields,
        };
        if *low > max_fields {
            continue;
        }
        for i in *low..=high {
            if !seen.contains(&i) {
                seen.insert(i);
                result.push(i);
            }
        }
    }
    result
}

