                    vec.push(Regex::new("$^").unwrap());
                }
            }
        }
        vec
    } else {
        Vec::new()
    };

    // For each input file, process
    // If no input files, read from stdin
    if input_files.is_empty() {
        // stdin
        let stdin = io::stdin();
        let reader = BufReader::new(stdin);
        if let Err(e) = process_reader(reader, &mut writer, &literal_delim, &regex_delim, &fields_ranges, &exclude_ranges, &header_fields, &exclude_headers, &header_field_regexes, &exclude_header_regexes, header_is_regex, header_mode, &final_output_delim, crlf, try_compress) {
