            let mut reader: Box<dyn BufRead> = if try_decompress {
                match try_decompress_file(file_path) {
                    Ok((r, _)) => r,
                    Err((msg, is_external)) => {
                        // msg is error message to print? For internal, msg is "invalid gzip header" etc.
