            // So we need to process per file, not combine

            if let Err(e) = process_reader_file(reader, &mut writer, &literal_delim, &regex_delim, &fields_ranges, &exclude_ranges, &header_fields, &exclude_headers, &header_field_regexes, &exclude_header_regexes, header_is_regex, header_mode, &final_output_delim, crlf, file_idx == 0) {
                eprintln!("Error: {}", e);
