fn unescape_literal(s: &str) -> String {
    let mut result = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            if let Some(next) = chars.next() {
                match next {
                    't' => result.push('\t'),
                    'n' => result.push('\n'),
                    'r' => result.push('\r'),
                    '0' => result.push('\0'),
                    '\\' => result.push('\\'),
                    'x' => {
                        // Need 2 hex digits
                        let h1 = chars.next();
                        let h2 = chars.next();
                        if let (Some(c1), Some(c2)) = (h1, h2) {
                            if c1.is_ascii_hexdigit() && c2.is_ascii_hexdigit() {
                                let hex_str = format!("{}{}", c1, c2);
                                if let Ok(byte) = u8::from_str_radix(&hex_str, 16) {
                                    result.push(byte as char);
                                } else {
                                    // Invalid hex, keep literal \x + chars?
                                    result.push('\\');
                                    result.push('x');
                                    result.push(c1);
                                    result.push(c2);
                                }
                            } else {
                                // Not hex, keep literal \x + chars
                                result.push('\\');
                                result.push('x');
                                result.push(c1);
                                result.push(c2);
                            }
                        } else {
                            // Not enough chars for \x, keep literal
                            result.push('\\');
                            result.push('x');
                            if let Some(c1) = h1 {
                                result.push(c1);
                            }
                            if let Some(c2) = h2 {
                                result.push(c2);
                            }
                        }
                    }
                    _ => {
                        // For other escapes like \s, \d, keep as \ + char
                        result.push('\\');
                        result.push(next);
                    }
                }
            } else {
                result.push('\\');
            }
        } else {
            result.push(c);
        }
    }
    result
}

fn parse_field_spec(s: &str) -> Result<Vec<(usize, Option<usize>)>, String> {
    // Returns Vec of (low, high Option) where None means inf
    // Error string is like "Fields and positions are numbered from 1: 0" or "High end of range less than low end of range: 1-0" or "Failed to parse field: X"
    let mut ranges = Vec::new();
    for part in s.split(',') {
        if part.is_empty() {
            return Err(format!("Failed to parse field: "));
        }
        if part == "-" {
            return Err(format!("Failed to parse field: "));
        }
        // Check for multiple dashes: if more than one '-' and not leading/trailing case?
        // For simplicity, if count('-') >1, error
        if part.matches('-').count() > 1 {
            return Err(format!("Failed to parse field: {}", part));
        }
        if part.contains('-') {
            let mut split = part.splitn(2, '-');
            let left = split.next().unwrap();
            let right = split.next().unwrap();
            if left.is_empty() && right.is_empty() {
                return Err(format!("Failed to parse field: "));
            }
            if left.is_empty() {
                // -M
                match right.parse::<usize>() {
                    Ok(high) => {
                        if high == 0 {
                            return Err(format!("Fields and positions are numbered from 1: 0"));
                        }
                        ranges.push((1, Some(high)));
                    }
                    Err(_) => {
                        return Err(format!("Failed to parse field: {}", part));
                    }
                }
            } else if right.is_empty() {
                // N-
                match left.parse::<usize>() {
                    Ok(low) => {
                        if low == 0 {
                            return Err(format!("Fields and positions are numbered from 1: 0"));
                        }
                        ranges.push((low, None));
                    }
                    Err(_) => {
                        return Err(format!("Failed to parse field: {}", part));
                    }
                }
            } else {
                // N-M
                let low_res = left.parse::<usize>();
                let high_res = right.parse::<usize>();
                match (low_res, high_res) {
                    (Ok(low), Ok(high)) => {
                        if low == 0 || high == 0 {
                            return Err(format!("Fields and positions are numbered from 1: 0"));
                        }
                        if low > high {
                            return Err(format!("High end of range less than low end of range: {}", part));
                        }
                        ranges.push((low, Some(high)));
                    }
                    _ => {
                        return Err(format!("Failed to parse field: {}", part));
                    }
                }
            }
        } else {
            // single number
            match part.parse::<usize>() {
                Ok(n) => {
                    if n == 0 {
                        return Err(format!("Fields and positions are numbered from 1: 0"));
                    }
                    ranges.push((n, Some(n)));
                }
                Err(_) => {
                    return Err(format!("Failed to parse field: {}", part));
                }
            }
        }
    }
    Ok(ranges)
}

fn expand_ranges_for_line(ranges: &Vec<(usize, Option<usize>)>, max_fields: usize) -> Vec<usize> {
    let mut seen = HashSet::new();
    let mut result = Vec::new();
    for (low, high_opt) in ranges {
        let high = match high_opt {
            Some(h) => std::cmp::min(*h, max_fields),
            None => max_fields,
        };
        if *low > max_fields {
            continue;
        }
        for i in *low..=high {
            if !seen.contains(&i) {
                seen.insert(i);
                result.push(i);
            }
        }
    }
    result
}

fn process_reader<R: BufRead, W: Write>(
    reader: R,
    writer: &mut W,
    literal_delim: &Option<String>,
    regex_delim: &Option<Regex>,
    fields_ranges: &Option<Vec<(usize, Option<usize>)>>,
    exclude_ranges: &Option<Vec<(usize, Option<usize>)>>,
    header_fields: &Vec<String>,
    exclude_headers: &Vec<String>,
    header_field_regexes: &Vec<Regex>,
    exclude_header_regexes: &Vec<Regex>,
    header_is_regex: bool,
    header_mode: bool,
    output_delim: &str,
    crlf: bool,
    try_compress: bool,
) -> std::io::Result<()> {
    // For stdin, header mode: first line is header
    let mut lines = reader.lines();
    let mut is_first_line = true;
    let mut header_indices: Vec<usize> = Vec::new();
    let mut exclude_header_indices: Vec<usize> = Vec::new();
    let mut header_field_names: Vec<String> = Vec::new();

    // For stdin, we process as single file
    let mut line_buf = String::new();
    // Use manual reading to handle crlf
    // Actually BufRead::lines() strips \n and \r\n? In Rust, lines() strips trailing \n and \r\n? Let's check: lines() splits on \n and strips \n, and also strips \r if present? In Rust, lines() does not include \n, and if line ends with \r\n, it strips \r\n? Actually `lines()` strips the trailing newline, which includes \n and \r\n? The docs say it does not include newline, and for \r\n it strips \r\n? Let's assume it strips \r\n as well? Need to handle crlf flag ourselves for output.
    // Instead we will read raw and handle.

    // We'll re-implement reading with handling for crlf flag.

    // For simplicity, we will read all content and split.

    // But for now, use lines() and handle crlf output.

    // Actually we need to handle input crlf: if crlf flag set, we should strip \r\n as terminator, else strip \n only.
    // The lines() method in Rust strips \n and \r\n both? Let's check: In Rust, `BufRead::lines()` strips trailing \n or \r\n? I think it strips \n and \r\n? The docs: "The output is an iterator over the lines of this reader. Each line is a string that does not include the newline. For \r\n, both are stripped."
