fn split_line(line: &str, literal_delim: &Option<String>, regex_delim: &Option<Regex>) -> Vec<String> {
    if let Some(lit) = literal_delim {
        if lit.is_empty() {
            return vec![line.to_string()];
        }
        // Use split
        line.split(lit).map(|s| s.to_string()).collect()
    } else if let Some(re) = regex_delim {
        // Use regex split
        // re.split returns iterator that includes empty strings?
        re.split(line).map(|s| s.to_string()).collect()
    } else {
        // default \s+ ? Actually if both None, it means delimiter empty, treat as whole line?
        vec![line.to_string()]
    }
}

fn try_decompress_file(path: &str) -> Result<(Box<dyn BufRead>, bool), (String, bool)> {
    // Returns Ok((reader, is_compressed)) or Err((error_message, is_external))
    // is_external true means error came from external binary and should be wrapped with dashed lines
    // is_external false means internal error

    let path_obj = std::path::Path::new(path);
    let file_name = path_obj.file_name().and_then(|n| n.to_str()).unwrap_or("");

    // List of recognized extensions
    // We'll check suffixes in order of longest first

    let recognized_external_gz = ["tar.Z", "tgz"];
    let recognized_internal_gz = ["tar.gz", "taz.gz", "gz"];
    let recognized_bz2 = ["tar.bz2", "tbz2", "bz2"];
    let recognized_xz_auto = ["tar.xz", "txz", "xz"];
    let recognized_xz_lzma = ["tar.lzma", "lzma"];

    // Also need to handle .Z
    let recognized_external_gz_z = ["Z"];

    // Check internal gz first? Let's check order: For .tar.gz, it should be internal, not external. For .tar.Z, external.

    let mut ext_type = None;
    let mut is_internal = false;

    // Check for .taz.gz
    if file_name.ends_with(".taz.gz") {
        ext_type = Some("gz");
        is_internal = true;
    } else if file_name.ends_with(".tar.gz") {
        ext_type = Some("gz");
        is_internal = true;
    } else if file_name.ends_with(".tar.Z") {
        ext_type = Some("Z");
        is_internal = false;
    } else if file_name.ends_with(".tar.bz2") {
        ext_type = Some("bz2");
        is_internal = false;
    } else if file_name.ends_with(".tar.xz") {
        ext_type = Some("xz");
        is_internal = false;
    } else if file_name.ends_with(".tar.lzma") {
        ext_type = Some("lzma");
        is_internal = false;
    } else if file_name.ends_with(".gz") {
        ext_type = Some("gz");
        is_internal = true;
    } else if file_name.ends_with(".Z") {
        ext_type = Some("Z");
        is_internal = false;
    } else if file_name.ends_with(".tgz") {
        ext_type = Some("tgz");
        is_internal = false;
    } else if file_name.ends_with(".tbz2") {
        ext_type = Some("tbz2");
        is_internal = false;
    } else if file_name.ends_with(".bz2") {
        ext_type = Some("bz2");
        is_internal = false;
    } else if file_name.ends_with(".txz") {
        ext_type = Some("txz");
        is_internal = false;
    } else if file_name.ends_with(".xz") {
        ext_type = Some("xz");
        is_internal = false;
    } else if file_name.ends_with(".lzma") {
        ext_type = Some("lzma");
        is_internal = false;
    } else if file_name.ends_with(".taz.gz") {
        ext_type = Some("gz");
        is_internal = true;
    } else {
        // Not recognized
        // Return plain file reader
        match File::open(path) {
            Ok(f) => return Ok((Box::new(BufReader::new(f)), false)),
            Err(e) => return Err((format!("{} (os error {})", e, e.raw_os_error().unwrap_or(2)), false)),
        }
    }

    // Now check if binary exists for external
    // For internal gz, we attempt to decompress using flate2

    if is_internal {
        // internal gzip
        match File::open(path) {
            Ok(f) => {
                // Try to read as gzip
                // We need to attempt to decompress and see if error
                // We'll read file into memory and try to decompress using GzDecoder
                use std::io::Read;
                let mut decoder = flate2::read::GzDecoder::new(f);
                let mut decompressed = Vec::new();
                match decoder.read_to_end(&mut decompressed) {
                    Ok(_) => {
                        // Decompressed successfully, return reader over decompressed content
                        let reader = std::io::Cursor::new(decompressed);
                        Ok((Box::new(BufReader::new(reader)), true))
                    }
                    Err(e) => {
                        // Check error type to produce appropriate message
                        // For gzip, errors are "invalid gzip header" or "unexpected end of file"
                        let err_str = e.to_string();
                        // Heuristic: if error contains "invalid" or "header", return that, else "unexpected end of file"
                        if err_str.to_lowercase().contains("invalid") || err_str.to_lowercase().contains("header") {
                            Err(("invalid gzip header".to_string(), false))
                        } else {
                            Err(("unexpected end of file".to_string(), false))
                        }
                    }
                }
            }
            Err(e) => Err((format!("{} (os error {})", e, e.raw_os_error().unwrap_or(2)), false)),
        }
    } else {
        // external
        // Determine binary and args
        let (binary, args): (&str, Vec<&str>) = match ext_type.unwrap() {
            "Z" | "tgz" | "tar.Z" => ("gzip", vec!["-dc", path]),
            "bz2" | "tbz2" | "tar.bz2" => ("bzip2", vec!["-dc", path]),
            "xz" | "txz" | "tar.xz" => ("xz", vec!["-dc", path]),
            "lzma" | "tar.lzma" => ("xz", vec!["--format=lzma", "-dc", path]),
            "gz" => ("gzip", vec!["-dc", path]), // though internal, but for external case like .Z etc we already handled, but for safety
            _ => {
                // fallback to plain
                match File::open(path) {
                    Ok(f) => return Ok((Box::new(BufReader::new(f)), false)),
                    Err(e) => return Err((format!("{} (os error {})", e, e.raw_os_error().unwrap_or(2)), false)),
                }
            }
        };

        // Check if binary exists
        if which::which(binary).is_err() {
            // Binary not found, treat as plain file
            match File::open(path) {
                Ok(f) => return Ok((Box::new(BufReader::new(f)), false)),
                Err(e) => return Err((format!("{} (os error {})", e, e.raw_os_error().unwrap_or(2)), false)),
            }
        }

        // Run binary
        let output = std::process::Command::new(binary)
            .args(&args)
            .output();

        match output {
            Ok(out) => {
                if out.status.success() {
                    let reader = std::io::Cursor::new(out.stdout);
                    Ok((Box::new(BufReader::new(reader)), true))
                } else {
                    // Error from binary, capture stderr
                    let stderr = String::from_utf8_lossy(&out.stderr).trim().to_string();
                    // Format: "<binary>: <file>: <error>"
                    // For gzip, error may already contain file path, e.g., "gzip: /tmp/file.Z: not in gzip format"
                    // For bzip2, "bzip2: /tmp/file.bz2 is not a bzip2 file."
                    // For xz, "xz: /tmp/file.xz: File format not recognized"
                    // We should use stderr as is if it already contains file path, else construct?
                    // For simplicity, if stderr is empty, use stdout? But binary errors go to stderr
                    let msg = if stderr.is_empty() {
                        format!("{}: {}: unknown error", binary, path)
                    } else {
                        stderr
                    };
                    Err((msg, true))
                }
            }
            Err(e) => {
                // Failed to execute binary
                Err((format!("{}: {}: {}", binary, path, e), true))
            }
        }
    }
}

