                    for idx in excl {
                        exclude_set_for_line.insert(idx);
                    }
                }
                for idx in exclude_selected.iter() {
                    if *idx <= max_fields {
                        exclude_set_for_line.insert(*idx);
                    }
                }
            }

            let mut final_selected: Vec<usize> = Vec::new();
            for idx in selected {
                if !exclude_set_for_line.contains(&idx) {
                    final_selected.push(idx);
                }
            }

            let mut output_fields: Vec<String> = Vec::new();
            let mut seen_output = HashSet::new();
            for idx in final_selected {
                if idx ==0 || idx > fields.len() {
                    continue;
                }
                if seen_output.contains(&idx) {
                    continue;
                }
                seen_output.insert(idx);
                output_fields.push(fields[idx-1].clone());
            }

            let out_line = output_fields.join(output_delim);
            if has_newline {
                if crlf {
                    writeln!(writer, "{}\r", out_line).unwrap();
                } else {
                    writeln!(writer, "{}", out_line).unwrap();
                }
            } else {
                if out_line.is_empty() && max_fields==0 {
                    continue;
                }
                if crlf {
                    write!(writer, "{}\r", out_line).unwrap();
                } else {
                    write!(writer, "{}", out_line).unwrap();
                }
            }
        }

    } else {
        for (line_idx, line) in raw_lines.iter().enumerate() {
