cat > src/main.rs <<'RS'
use clap::{Arg, ArgAction, Command};
use regex::Regex;
use std::collections::{HashSet};
use std::io::{self, BufRead, BufReader, Write};
use std::fs::File;
use std::process;

fn current_timestamp() -> String {
    chrono::Utc::now().format("%Y-%m-%dT%H:%M:%SZ").to_string()
}

const HELP_SHORT: &str = include_str!("../help_short.txt");
const HELP_LONG: &str = include_str!("../help_long.txt");
const VERSION: &str = "hck git:0e2b6ba";

fn main() {
    let args: Vec<String> = std::env::args().collect();
    // Debug: if -h, print len and exit
    if args.iter().any(|a| a == "-h") && args.iter().any(|a| a == "--debug-len") {
        eprintln!("HELP_SHORT len = {}", HELP_SHORT.len());
        eprintln!("last 10 bytes: {:?}", HELP_SHORT.as_bytes()[HELP_SHORT.len().saturating_sub(10)..].iter().map(|b| *b as char).collect::<Vec<_>>());
        print!("{}", HELP_SHORT);
        process::exit(0);
    }

    if args.iter().any(|a| a == "-V" || a == "--version") {
        println!("{}", VERSION);
        process::exit(0);
    }

    let has_long_help = args.iter().any(|a| a == "--help");
    let has_short_help = args.iter().any(|a| a == "-h");

    if has_long_help {
        print!("{}", HELP_LONG);
        process::exit(0);
    }
    if has_short_help {
        print!("{}", HELP_SHORT);
        process::exit(0);
    }

    let cmd = Command::new("executable")
        .disable_help_flag(true)
        .disable_version_flag(true)
        .arg(Arg::new("input").num_args(0..))
        .arg(Arg::new("output").short('o').long("output").value_name("OUTPUT"))
        .arg(Arg::new("delimiter").short('d').long("delimiter").value_name("DELIMITER").default_value(r"\s+"))
        .arg(Arg::new("delim_is_literal").short('L').long("delim-is-literal").action(ArgAction::SetTrue))
        .arg(Arg::new("use_input_delim").short('I').long("use-input-delim").action(ArgAction::SetTrue))
        .arg(Arg::new("output_delimiter").short('D').long("output-delimiter").value_name("OUTPUT_DELIMITER").default_value("\t"))
        .arg(Arg::new("fields").short('f').long("fields").value_name("FIELDS"))
        .arg(Arg::new("exclude").short('e').long("exclude").value_name("EXCLUDE"))
        .arg(Arg::new("exclude_header").short('E').long("exclude-header").value_name("EXCLUDE_HEADER").action(ArgAction::Append))
        .arg(Arg::new("header_field").short('F').long("header-field").value_name("HEADER_FIELD").action(ArgAction::Append))
        .arg(Arg::new("header_is_regex").short('r').long("header-is-regex").action(ArgAction::SetTrue))
        .arg(Arg::new("try_decompress").short('z').long("try-decompress").action(ArgAction::SetTrue))
        .arg(Arg::new("try_compress").short('Z').long("try-compress").action(ArgAction::SetTrue))
        .arg(Arg::new("compression_threads").short('t').long("compression-threads").value_name("COMPRESSION_THREADS").default_value("4"))
        .arg(Arg::new("compression_level").short('l').long("compression-level").value_name("COMPRESSION_LEVEL").default_value("6"))
        .arg(Arg::new("no_mmap").long("no-mmap").action(ArgAction::SetTrue))
        .arg(Arg::new("crlf").long("crlf").action(ArgAction::SetTrue))
        .arg(Arg::new("help").short('h').long("help").action(ArgAction::SetTrue).hide(true))
        .arg(Arg::new("version").short('V').long("version").action(ArgAction::SetTrue).hide(true));

    let matches = cmd.try_get_matches();
    let matches = match matches {
        Ok(m) => m,
        Err(e) => { e.exit(); }
    };

    let input_files: Vec<String> = matches.get_many::<String>("input").map(|v| v.map(|s| s.to_string()).collect()).unwrap_or_default();
    let output_file = matches.get_one::<String>("output").map(|s| s.to_string());
    let delimiter_str = matches.get_one::<String>("delimiter").unwrap().to_string();
    let delim_is_literal = matches.get_flag("delim_is_literal");
    let use_input_delim = matches.get_flag("use_input_delim");
    let output_delimiter_arg = matches.get_one::<String>("output_delimiter").map(|s| s.to_string()).unwrap_or("\t".to_string());
    let output_delim_is_default = matches.value_source("output_delimiter").map(|s| s == clap::parser::ValueSource::DefaultValue).unwrap_or(true);
    let fields_opt = matches.get_one::<String>("fields").map(|s| s.to_string());
    let exclude_opt = matches.get_one::<String>("exclude").map(|s| s.to_string());
    let exclude_headers: Vec<String> = matches.get_many::<String>("exclude_header").map(|v| v.map(|s| s.to_string()).collect()).unwrap_or_default();
    let header_fields: Vec<String> = matches.get_many::<String>("header_field").map(|v| v.map(|s| s.to_string()).collect()).unwrap_or_default();
    let header_is_regex = matches.get_flag("header_is_regex");
    let try_decompress = matches.get_flag("try_decompress");
    let try_compress = matches.get_flag("try_compress");
    let compression_threads_str = matches.get_one::<String>("compression_threads").unwrap().to_string();
    let compression_level_str = matches.get_one::<String>("compression_level").unwrap().to_string();
    let _no_mmap = matches.get_flag("no_mmap");
    let crlf = matches.get_flag("crlf");

    if let Err(_) = compression_threads_str.parse::<u32>() {
        eprintln!("error: invalid value '{}' for '--compression-threads <COMPRESSION_THREADS>': invalid digit found in string\n\nFor more information, try '--help'.", compression_threads_str);
        process::exit(2);
    }
    if let Err(_) = compression_level_str.parse::<u32>() {
        eprintln!("error: invalid value '{}' for '--compression-level <COMPRESSION_LEVEL>': invalid digit found in string\n\nFor more information, try '--help'.", compression_level_str);
        process::exit(2);
    }

    let fields_ranges = if let Some(ref f) = fields_opt {
        match parse_field_spec(f) {
            Ok(r) => Some(r),
            Err(msg) => {
                let ts = current_timestamp();
                eprintln!("[{} ERROR hck] {}", ts, msg);
                process::exit(1);
            }
        }
    } else { None };

    let exclude_ranges = if let Some(ref e) = exclude_opt {
        match parse_field_spec(e) {
            Ok(r) => Some(r),
            Err(msg) => {
                let ts = current_timestamp();
                eprintln!("[{} ERROR hck] {}", ts, msg);
                process::exit(1);
            }
        }
    } else { None };

    let input_delim_literal_string: Option<String> = if delim_is_literal { Some(unescape_literal(&delimiter_str)) } else { None };
    let output_delim_processed: String = if output_delim_is_default { "\t".to_string() } else { unescape_literal(&output_delimiter_arg) };
    let final_output_delim = if use_input_delim && delim_is_literal && output_delim_is_default {
        input_delim_literal_string.clone().unwrap_or(output_delim_processed)
    } else {
        output_delim_processed
    };

    let regex_delim: Option<Regex> = if !delim_is_literal {
        if delimiter_str.is_empty() { None } else {
            match Regex::new(&delimiter_str) {
                Ok(r) => Some(r),
                Err(e) => {
                    let ts = current_timestamp();
                    eprintln!("[{} ERROR hck] Invalid regex: {}", ts, e);
                    process::exit(1);
                }
            }
        }
    } else { None };

    let literal_delim: Option<String> = if delim_is_literal {
        if delimiter_str.is_empty() { None } else { Some(unescape_literal(&delimiter_str)) }
    } else { None };

    let output_writer: Box<dyn Write> = if let Some(out_path) = output_file {
        match File::create(&out_path) {
            Ok(f) => {
                if try_compress {
                    let level = compression_level_str.parse::<u32>().unwrap_or(6);
                    let encoder = flate2::write::GzEncoder::new(f, flate2::Compression::new(level));
                    Box::new(encoder)
                } else { Box::new(f) }
            }
            Err(e) => {
                eprintln!("Error: Failed to open {} for writing.\n\nCaused by:\n    {}\n", out_path, e);
                process::exit(1);
            }
        }
    } else {
        if try_compress {
            let level = compression_level_str.parse::<u32>().unwrap_or(6);
            let stdout = io::stdout();
            let encoder = flate2::write::GzEncoder::new(stdout, flate2::Compression::new(level));
            Box::new(encoder)
        } else {
            Box::new(io::stdout())
        }
    };

    let mut writer = std::io::BufWriter::new(output_writer);
    let header_mode = !header_fields.is_empty() || !exclude_headers.is_empty();

    let header_field_regexes: Vec<Regex> = if header_is_regex {
        let mut vec = Vec::new();
        for pat in &header_fields {
            match Regex::new(pat) {
                Ok(r) => vec.push(r),
                Err(_) => { vec.push(Regex::new("$^").unwrap()); }
            }
        }
        vec
    } else { Vec::new() };

    let exclude_header_regexes: Vec<Regex> = if header_is_regex {
        let mut vec = Vec::new();
        for pat in &exclude_headers {
            match Regex::new(pat) {
                Ok(r) => vec.push(r),
                Err(_) => { vec.push(Regex::new("$^").unwrap()); }
            }
        }
        vec
    } else { Vec::new() };

    if input_files.is_empty() {
        let stdin = io::stdin();
        let reader = BufReader::new(stdin);
        if let Err(e) = process_stdin(reader, &mut writer, &literal_delim, &regex_delim, &fields_ranges, &exclude_ranges, &header_fields, &exclude_headers, &header_field_regexes, &exclude_header_regexes, header_is_regex, header_mode, &final_output_delim, crlf) {
            eprintln!("Error: {}", e);
            process::exit(1);
        }
    } else {
        for file_path in input_files.iter() {
            if file_path == "-" {
                let stdin = io::stdin();
                let reader = BufReader::new(stdin);
                if let Err(e) = process_stdin(reader, &mut writer, &literal_delim, &regex_delim, &fields_ranges, &exclude_ranges, &header_fields, &exclude_headers, &header_field_regexes, &exclude_header_regexes, header_is_regex, header_mode, &final_output_delim, crlf) {
                    eprintln!("Error: {}", e);
                    process::exit(1);
                }
                continue;
            }
            let path = std::path::Path::new(file_path);
            if !path.exists() {
                let ts = current_timestamp();
                eprintln!("[{} ERROR hck] No such file or directory (os error 2)", ts);
                continue;
            }
            let reader: Box<dyn BufRead> = if try_decompress {
                match try_decompress_file(file_path) {
                    Ok((r, _)) => r,
                    Err((msg, is_external)) => {
                        if is_external {
                            let ts = current_timestamp();
                            eprintln!("[{} ERROR hck] \n    -------------------------------------------------------------------------------\n    {}\n    -------------------------------------------------------------------------------", ts, msg);
                        } else {
                            let ts = current_timestamp();
                            eprintln!("[{} ERROR hck] {}", ts, msg);
                        }
                        continue;
                    }
                }
            } else {
                match File::open(file_path) {
                    Ok(f) => Box::new(BufReader::new(f)),
                    Err(e) => {
                        let ts = current_timestamp();
                        eprintln!("[{} ERROR hck] {} (os error {})", ts, e, e.raw_os_error().unwrap_or(2));
                        continue;
                    }
                }
            };
            if let Err(e) = process_file(reader, &mut writer, &literal_delim, &regex_delim, &fields_ranges, &exclude_ranges, &header_fields, &exclude_headers, &header_field_regexes, &exclude_header_regexes, header_is_regex, header_mode, &final_output_delim, crlf) {
                eprintln!("Error: {}", e);
                process::exit(1);
            }
        }
    }

    writer.flush().unwrap();
}

fn unescape_literal(s: &str) -> String {
    let mut result = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            if let Some(next) = chars.next() {
                match next {
                    't' => result.push('\t'),
                    'n' => result.push('\n'),
                    'r' => result.push('\r'),
                    '0' => result.push('\0'),
                    '\\' => result.push('\\'),
                    'x' => {
                        let h1 = chars.next();
                        let h2 = chars.next();
                        if let (Some(c1), Some(c2)) = (h1, h2) {
                            if c1.is_ascii_hexdigit() && c2.is_ascii_hexdigit() {
                                let hex_str = format!("{}{}", c1, c2);
                                if let Ok(byte) = u8::from_str_radix(&hex_str, 16) {
                                    result.push(byte as char);
                                } else {
                                    result.push('\\'); result.push('x'); result.push(c1); result.push(c2);
                                }
                            } else {
                                result.push('\\'); result.push('x'); result.push(c1); result.push(c2);
                            }
                        } else {
                            result.push('\\'); result.push('x');
                            if let Some(c1) = h1 { result.push(c1); }
                            if let Some(c2) = h2 { result.push(c2); }
                        }
                    }
                    _ => { result.push('\\'); result.push(next); }
                }
            } else { result.push('\\'); }
        } else { result.push(c); }
    }
    result
}

fn parse_field_spec(s: &str) -> Result<Vec<(usize, Option<usize>)>, String> {
    let mut ranges = Vec::new();
    for part in s.split(',') {
        if part.is_empty() { return Err(format!("Failed to parse field: ")); }
        if part == "-" { return Err(format!("Failed to parse field: ")); }
        if part.matches('-').count() > 1 { return Err(format!("Failed to parse field: {}", part)); }
        if part.contains('-') {
            let mut split = part.splitn(2, '-');
            let left = split.next().unwrap();
            let right = split.next().unwrap();
            if left.is_empty() && right.is_empty() { return Err(format!("Failed to parse field: ")); }
            if left.is_empty() {
                match right.parse::<usize>() {
                    Ok(high) => {
                        if high == 0 { return Err(format!("Fields and positions are numbered from 1: 0")); }
                        ranges.push((1, Some(high)));
                    }
                    Err(_) => { return Err(format!("Failed to parse field: {}", part)); }
                }
            } else if right.is_empty() {
                match left.parse::<usize>() {
                    Ok(low) => {
                        if low == 0 { return Err(format!("Fields and positions are numbered from 1: 0")); }
                        ranges.push((low, None));
                    }
                    Err(_) => { return Err(format!("Failed to parse field: {}", part)); }
                }
            } else {
                let low_res = left.parse::<usize>();
                let high_res = right.parse::<usize>();
                match (low_res, high_res) {
                    (Ok(low), Ok(high)) => {
                        if low == 0 || high == 0 { return Err(format!("Fields and positions are numbered from 1: 0")); }
                        if low > high { return Err(format!("High end of range less than low end of range: {}", part)); }
                        ranges.push((low, Some(high)));
                    }
                    _ => { return Err(format!("Failed to parse field: {}", part)); }
                }
            }
        } else {
            match part.parse::<usize>() {
                Ok(n) => {
                    if n == 0 { return Err(format!("Fields and positions are numbered from 1: 0")); }
                    ranges.push((n, Some(n)));
                }
                Err(_) => { return Err(format!("Failed to parse field: {}", part)); }
            }
        }
    }
    Ok(ranges)
}

fn expand_ranges_for_line(ranges: &Vec<(usize, Option<usize>)>, max_fields: usize) -> Vec<usize> {
    let mut seen = HashSet::new();
    let mut result = Vec::new();
    for (low, high_opt) in ranges {
        let high = match high_opt { Some(h) => std::cmp::min(*h, max_fields), None => max_fields };
        if *low > max_fields { continue; }
        for i in *low..=high {
            if !seen.contains(&i) { seen.insert(i); result.push(i); }
        }
    }
    result
}

fn split_line(line: &str, literal_delim: &Option<String>, regex_delim: &Option<Regex>) -> Vec<String> {
    if let Some(lit) = literal_delim {
        if lit.is_empty() { return vec![line.to_string()]; }
        line.split(lit).map(|s| s.to_string()).collect()
    } else if let Some(re) = regex_delim {
        re.split(line).map(|s| s.to_string()).collect()
    } else {
        vec![line.to_string()]
    }
}

fn binary_exists(bin: &str) -> bool {
    if let Some(paths) = std::env::var_os("PATH") {
        for path in std::env::split_paths(&paths) {
            let full = path.join(bin);
            if full.exists() && full.is_file() { return true; }
        }
    }
    false
}

fn try_decompress_file(path: &str) -> Result<(Box<dyn BufRead>, bool), (String, bool)> {
    let file_name = std::path::Path::new(path).file_name().and_then(|n| n.to_str()).unwrap_or("");
    let mut ext_type: Option<&str> = None;
    let mut is_internal = false;

    if file_name.ends_with(".taz.gz") { ext_type = Some("gz"); is_internal = true; }
    else if file_name.ends_with(".tar.gz") { ext_type = Some("gz"); is_internal = true; }
    else if file_name.ends_with(".tar.Z") { ext_type = Some("Z"); is_internal = false; }
    else if file_name.ends_with(".tar.bz2") { ext_type = Some("bz2"); is_internal = false; }
    else if file_name.ends_with(".tar.xz") { ext_type = Some("xz"); is_internal = false; }
    else if file_name.ends_with(".tar.lzma") { ext_type = Some("lzma"); is_internal = false; }
    else if file_name.ends_with(".gz") { ext_type = Some("gz"); is_internal = true; }
    else if file_name.ends_with(".Z") { ext_type = Some("Z"); is_internal = false; }
    else if file_name.ends_with(".tgz") { ext_type = Some("tgz"); is_internal = false; }
    else if file_name.ends_with(".tbz2") { ext_type = Some("tbz2"); is_internal = false; }
    else if file_name.ends_with(".bz2") { ext_type = Some("bz2"); is_internal = false; }
    else if file_name.ends_with(".txz") { ext_type = Some("txz"); is_internal = false; }
    else if file_name.ends_with(".xz") { ext_type = Some("xz"); is_internal = false; }
    else if file_name.ends_with(".lzma") { ext_type = Some("lzma"); is_internal = false; }
    else {
        match File::open(path) {
            Ok(f) => return Ok((Box::new(BufReader::new(f)), false)),
            Err(e) => return Err((format!("{} (os error {})", e, e.raw_os_error().unwrap_or(2)), false)),
        }
    }

    if is_internal {
        match File::open(path) {
            Ok(f) => {
                use std::io::Read;
                let mut decoder = flate2::read::GzDecoder::new(f);
                let mut decompressed = Vec::new();
                match decoder.read_to_end(&mut decompressed) {
                    Ok(_) => {
                        let reader = std::io::Cursor::new(decompressed);
                        Ok((Box::new(BufReader::new(reader)), true))
                    }
                    Err(e) => {
                        let err_str = e.to_string().to_lowercase();
                        if err_str.contains("invalid") || err_str.contains("header") {
                            Err(("invalid gzip header".to_string(), false))
                        } else {
                            Err(("unexpected end of file".to_string(), false))
                        }
                    }
                }
            }
            Err(e) => Err((format!("{} (os error {})", e, e.raw_os_error().unwrap_or(2)), false)),
        }
    } else {
        let (binary, args): (&str, Vec<&str>) = match ext_type.unwrap() {
            "Z" | "tgz" | "tar.Z" => ("gzip", vec!["-dc", path]),
            "bz2" | "tbz2" | "tar.bz2" => ("bzip2", vec!["-dc", path]),
            "xz" | "txz" | "tar.xz" => ("xz", vec!["-dc", path]),
            "lzma" | "tar.lzma" => ("xz", vec!["--format=lzma", "-dc", path]),
            "gz" => ("gzip", vec!["-dc", path]),
            _ => {
                match File::open(path) {
                    Ok(f) => return Ok((Box::new(BufReader::new(f)), false)),
                    Err(e) => return Err((format!("{} (os error {})", e, e.raw_os_error().unwrap_or(2)), false)),
                }
            }
        };

        if !binary_exists(binary) {
            match File::open(path) {
                Ok(f) => return Ok((Box::new(BufReader::new(f)), false)),
                Err(e) => return Err((format!("{} (os error {})", e, e.raw_os_error().unwrap_or(2)), false)),
            }
        }

        let output = std::process::Command::new(binary).args(&args).output();
        match output {
            Ok(out) => {
                if out.status.success() {
                    let reader = std::io::Cursor::new(out.stdout);
                    Ok((Box::new(BufReader::new(reader)), true))
                } else {
                    let stderr = String::from_utf8_lossy(&out.stderr).trim().to_string();
                    let msg = if stderr.is_empty() {
                        format!("{}: {}: unknown error", binary, path)
                    } else { stderr };
                    Err((msg, true))
                }
            }
            Err(e) => Err((format!("{}: {}: {}", binary, path, e), true)),
        }
    }
}

fn process_stdin<R: BufRead, W: Write>(
    mut reader: R,
    writer: &mut W,
    literal_delim: &Option<String>,
    regex_delim: &Option<Regex>,
    fields_ranges: &Option<Vec<(usize, Option<usize>)>>,
    exclude_ranges: &Option<Vec<(usize, Option<usize>)>>,
    header_fields: &Vec<String>,
    exclude_headers: &Vec<String>,
    header_field_regexes: &Vec<Regex>,
    exclude_header_regexes: &Vec<Regex>,
    header_is_regex: bool,
    header_mode: bool,
    output_delim: &str,
    crlf: bool,
) -> std::io::Result<()> {
    let mut buf = Vec::new();
    reader.read_to_end(&mut buf)?;
    let content = String::from_utf8_lossy(&buf);
    let mut raw_lines: Vec<String> = Vec::new();
    let mut has_newline_vec: Vec<bool> = Vec::new();
    for line in content.split_inclusive('\n') {
        let has_newline = line.ends_with('\n');
        let mut line_str = line.to_string();
        if has_newline {
            line_str.pop();
            if crlf {
                if line_str.ends_with('\r') { line_str.pop(); }
            }
        }
        raw_lines.push(line_str);
        has_newline_vec.push(has_newline);
    }
    if raw_lines.is_empty() { return Ok(()); }
    if header_mode {
        let header_line = &raw_lines[0];
        let header_fields_split = split_line(header_line, literal_delim, regex_delim);
        let mut seen_header = HashSet::new();
        let mut header_selected: Vec<usize> = Vec::new();
        for (pat_idx, pat) in header_fields.iter().enumerate() {
            let mut matched_indices: Vec<usize> = Vec::new();
            if header_is_regex {
                if let Some(re) = header_field_regexes.get(pat_idx) {
                    for (i, h) in header_fields_split.iter().enumerate() {
                        if re.is_match(h) { matched_indices.push(i+1); }
                    }
                }
            } else {
                for (i, h) in header_fields_split.iter().enumerate() {
                    if h == pat { matched_indices.push(i+1); }
                }
            }
            for idx in matched_indices {
                if !seen_header.contains(&idx) { seen_header.insert(idx); header_selected.push(idx); }
            }
        }
        let mut exclude_selected: Vec<usize> = Vec::new();
        let mut seen_exclude = HashSet::new();
        for (pat_idx, pat) in exclude_headers.iter().enumerate() {
            let mut matched_indices: Vec<usize> = Vec::new();
            if header_is_regex {
                if let Some(re) = exclude_header_regexes.get(pat_idx) {
                    for (i, h) in header_fields_split.iter().enumerate() {
                        if re.is_match(h) { matched_indices.push(i+1); }
                    }
                }
            } else {
                for (i, h) in header_fields_split.iter().enumerate() {
                    if h == pat { matched_indices.push(i+1); }
                }
            }
            for idx in matched_indices {
                if !seen_exclude.contains(&idx) { seen_exclude.insert(idx); exclude_selected.push(idx); }
            }
        }
        if !header_fields.is_empty() && header_selected.is_empty() {
            let ts = current_timestamp();
            eprintln!("[{} ERROR hck] No headers matched", ts);
        }
        let mut exclude_set_file: HashSet<usize> = HashSet::new();
        if let Some(ref er) = exclude_ranges {
            let excl = expand_ranges_for_line(er, header_fields_split.len());
            for idx in excl { exclude_set_file.insert(idx); }
        }
        for idx in exclude_selected.iter() { exclude_set_file.insert(*idx); }
        for (line_idx, line) in raw_lines.iter().enumerate() {
            let has_newline = has_newline_vec[line_idx];
            if !has_newline && line.is_empty() { continue; }
            let fields = split_line(line, literal_delim, regex_delim);
            let max_fields = fields.len();
            let mut selected: Vec<usize> = Vec::new();
            if line_idx == 0 {
                selected = header_selected.clone();
                if header_fields.is_empty() && fields_ranges.is_none() {
                    selected = (1..=max_fields).collect();
                } else if let Some(ref fr) = fields_ranges {
                    let numeric_selected = expand_ranges_for_line(fr, max_fields);
                    let mut seen = HashSet::new();
                    let mut combined = Vec::new();
                    for idx in header_selected.iter() {
                        if !seen.contains(idx) { seen.insert(*idx); combined.push(*idx); }
                    }
                    for idx in numeric_selected {
                        if !seen.contains(&idx) { seen.insert(idx); combined.push(idx); }
                    }
                    if !header_fields.is_empty() && fields_ranges.is_some() { combined.sort(); }
                    selected = combined;
                }
            } else {
                let mut combined = Vec::new();
                let mut seen = HashSet::new();
                for idx in header_selected.iter() {
                    if *idx <= max_fields && !seen.contains(idx) { seen.insert(*idx); combined.push(*idx); }
                }
                if let Some(ref fr) = fields_ranges {
                    let numeric_selected = expand_ranges_for_line(fr, max_fields);
                    for idx in numeric_selected {
                        if !seen.contains(&idx) { seen.insert(idx); combined.push(idx); }
                    }
                }
                if header_fields.is_empty() && fields_ranges.is_none() {
                    for i in 1..=max_fields { if !seen.contains(&i) { seen.insert(i); combined.push(i); } }
                }
                if !header_fields.is_empty() && fields_ranges.is_some() { combined.sort(); }
                selected = combined;
            }
            let mut exclude_set_for_line: HashSet<usize> = HashSet::new();
            if line_idx == 0 {
                exclude_set_for_line = exclude_set_file.clone();
            } else {
                if let Some(ref er) = exclude_ranges {
                    let excl = expand_ranges_for_line(er, max_fields);
                    for idx in excl { exclude_set_for_line.insert(idx); }
                }
                for idx in exclude_selected.iter() {
                    if *idx <= max_fields { exclude_set_for_line.insert(*idx); }
                }
            }
            let mut final_selected: Vec<usize> = Vec::new();
            for idx in selected { if !exclude_set_for_line.contains(&idx) { final_selected.push(idx); } }
            let mut output_fields: Vec<String> = Vec::new();
            let mut seen_output = HashSet::new();
            for idx in final_selected {
                if idx ==0 || idx > fields.len() { continue; }
                if seen_output.contains(&idx) { continue; }
                seen_output.insert(idx);
                output_fields.push(fields[idx-1].clone());
            }
            let out_line = output_fields.join(output_delim);
            if has_newline {
                if crlf { writeln!(writer, "{}\r", out_line).unwrap(); } else { writeln!(writer, "{}", out_line).unwrap(); }
            } else {
                if out_line.is_empty() && max_fields==0 { continue; }
                if crlf { write!(writer, "{}\r", out_line).unwrap(); } else { write!(writer, "{}", out_line).unwrap(); }
            }
        }
    } else {
        for (line_idx, line) in raw_lines.iter().enumerate() {
            let has_newline = has_newline_vec[line_idx];
            if !has_newline && line.is_empty() && raw_lines.len()==1 { continue; }
            let fields = split_line(line, literal_delim, regex_delim);
            let max_fields = fields.len();
            let mut selected: Vec<usize> = Vec::new();
            if let Some(ref fr) = fields_ranges {
                selected = expand_ranges_for_line(fr, max_fields);
            } else {
                selected = (1..=max_fields).collect();
            }
            let mut exclude_set = HashSet::new();
            if let Some(ref er) = exclude_ranges {
                let excl = expand_ranges_for_line(er, max_fields);
                for idx in excl { exclude_set.insert(idx); }
            }
            let mut final_selected: Vec<usize> = Vec::new();
            for idx in selected { if !exclude_set.contains(&idx) { final_selected.push(idx); } }
            let mut output_fields: Vec<String> = Vec::new();
            let mut seen_output = HashSet::new();
            for idx in final_selected {
                if idx ==0 || idx > fields.len() { continue; }
                if seen_output.contains(&idx) { continue; }
                seen_output.insert(idx);
                output_fields.push(fields[idx-1].clone());
            }
            let out_line = output_fields.join(output_delim);
            if has_newline {
                if crlf { writeln!(writer, "{}\r", out_line).unwrap(); } else { writeln!(writer, "{}", out_line).unwrap(); }
            } else {
                if out_line.is_empty() && max_fields==0 { continue; }
                if crlf { write!(writer, "{}\r", out_line).unwrap(); } else { write!(writer, "{}", out_line).unwrap(); }
            }
        }
    }
    Ok(())
}

